    function toMs(n) {
        n = Number(n) || 0;
        if (n <= 0) return 0;
        return n < 1e12 ? n * 1000 : n;
    }

    /** 解析 JWT 的 exp（毫秒）；非 JWT 或解析失败返回 0（不用 JWT 的项目自然得 0）。 */
    function jwtExpMs(token) {
        try {
            const p = JSON.parse(atob(String(token).split(".")[1].replace(/-/g, "+").replace(/_/g, "/")));
