      const totalDataBytes = g1b * g1d + g2b * g2d;
      const headerBits = 4 + (v <= 9 ? 8 : 16);
      if (Math.ceil((headerBits + bytes.length * 8) / 8) <= totalDataBytes) {
        ver = v;
        break;
      }
    }
    if (!ver) throw new Error('QR payload too long');

    const [ecLen, g1b, g1d, g2b, g2d, align] = QR_VER_M[ver];
    const totalDataBytes = g1b * g1d + g2b * g2d;

    // Encode byte-mode bitstream
    const bits = [];
    const pushBits = (val, len) => {
      for (let i = len - 1; i >= 0; i -= 1) bits.push((val >>> i) & 1);
    };
    pushBits(0b0100, 4); // Byte mode indicator
    pushBits(bytes.length, ver <= 9 ? 8 : 16);
    for (const b of bytes) pushBits(b, 8);
    const totalBits = totalDataBytes * 8;
    pushBits(0, Math.min(4, totalBits - bits.length));
    while (bits.length % 8 !== 0) bits.push(0);

    const dataCodewords = new Uint8Array(totalDataBytes);
    let idx = 0;
    for (let i = 0; i < bits.length; i += 8) {
      let byte = 0;
      for (let j = 0; j < 8; j += 1) byte = (byte << 1) | bits[i + j];
      dataCodewords[idx++] = byte;
    }
    const padBytes = [0xec, 0x11];
    let padIdx = 0;
    while (idx < totalDataBytes) {
      dataCodewords[idx++] = padBytes[padIdx++ & 1];
    }

    // Split into blocks & compute Reed-Solomon EC
    const blocks = [];
    let offset = 0;
    for (let i = 0; i < g1b; i += 1) {
      const d = dataCodewords.slice(offset, offset + g1d);
      offset += g1d;
      blocks.push({ data: d, ec: qrRsComputeEc(d, ecLen) });
    }
    for (let i = 0; i < g2b; i += 1) {
      const d = dataCodewords.slice(offset, offset + g2d);
      offset += g2d;
      blocks.push({ data: d, ec: qrRsComputeEc(d, ecLen) });
    }

    // Interleave data and EC codewords
    const finalBytes = [];
    const maxDataLen = Math.max(g1d, g2d);
    for (let i = 0; i < maxDataLen; i += 1) {
      for (const blk of blocks) {
        if (i < blk.data.length) finalBytes.push(blk.data[i]);
      }
    }
    for (let i = 0; i < ecLen; i += 1) {
      for (const blk of blocks) finalBytes.push(blk.ec[i]);
    }

    // Build matrix with function modules
    const size = ver * 4 + 17;
    const isFunc = Array.from({ length: size }, () => new Uint8Array(size));
    const base = Array.from({ length: size }, () => new Uint8Array(size));

    const setFunc = (r, c, dark) => {
      if (r < 0 || c < 0 || r >= size || c >= size) return;
      isFunc[r][c] = 1;
      base[r][c] = dark ? 1 : 0;
    };

    const drawFinder = (tr, tc) => {
      for (let dr = -1; dr <= 7; dr += 1) {
        for (let dc = -1; dc <= 7; dc += 1) {
          const dist = Math.max(Math.abs(dr - 3), Math.abs(dc - 3));
          const dark = dist !== 2 && dist !== 4;
          setFunc(tr + dr, tc + dc, dark);
        }
      }
    };
    drawFinder(0, 0);
    drawFinder(0, size - 7);
    drawFinder(size - 7, 0);

    // Alignment patterns
    for (const r of align) {
      for (const c of align) {
        if ((r === 6 && c === 6) || (r === 6 && c === size - 7) || (r === size - 7 && c === 6)) {
          continue;
        }
        for (let dr = -2; dr <= 2; dr += 1) {
          for (let dc = -2; dc <= 2; dc += 1) {
            setFunc(r + dr, c + dc, Math.max(Math.abs(dr), Math.abs(dc)) !== 1);
          }
        }
      }
    }

    // Timing patterns
    for (let i = 8; i < size - 8; i += 1) {
      setFunc(6, i, i % 2 === 0);
      setFunc(i, 6, i % 2 === 0);
    }

    // Reserve format info areas & dark module
    for (let i = 0; i <= 8; i += 1) {
      if (!isFunc[8][i]) setFunc(8, i, false);
      if (!isFunc[i][8]) setFunc(i, 8, false);
    }
    for (let i = size - 8; i < size; i += 1) {
      setFunc(8, i, false);
      setFunc(i, 8, false);
    }
    setFunc(size - 8, 8, true);

    // Version info for versions >= 7
    if (ver >= 7) {
      const vBits = qrBchVersion(ver);
      for (let i = 0; i < 18; i += 1) {
        const bit = Boolean((vBits >>> i) & 1);
        const a = Math.floor(i / 3);
        const b = size - 11 + (i % 3);
        setFunc(a, b, bit);
        setFunc(b, a, bit);
      }
    }

    // Place data bits in zigzag order
    let bitIndex = 0;
    const totalCodewordBits = finalBytes.length * 8;
    for (let right = size - 1; right >= 1; right -= 2) {
      if (right === 6) right = 5;
      const upward = ((right + 1) & 2) === 0;
      for (let vert = 0; vert < size; vert += 1) {
        const r = upward ? size - 1 - vert : vert;
        for (let j = 0; j < 2; j += 1) {
          const c = right - j;
          if (isFunc[r][c]) continue;
          let dark = 0;
          if (bitIndex < totalCodewordBits) {
            dark = (finalBytes[bitIndex >>> 3] >>> (7 - (bitIndex & 7))) & 1;
          }
          base[r][c] = dark;
          bitIndex += 1;
        }
      }
    }

    const applyMask = (mask) => {
      const mat = base.map((row) => Uint8Array.from(row));
      for (let r = 0; r < size; r += 1) {
        for (let c = 0; c < size; c += 1) {
          if (isFunc[r][c]) continue;
          let invert = false;
          switch (mask) {
            case 0: invert = (r + c) % 2 === 0; break;
            case 1: invert = r % 2 === 0; break;
            case 2: invert = c % 3 === 0; break;
            case 3: invert = (r + c) % 3 === 0; break;
            case 4: invert = (Math.floor(r / 2) + Math.floor(c / 3)) % 2 === 0; break;
            case 5: invert = ((r * c) % 2) + ((r * c) % 3) === 0; break;
            case 6: invert = (((r * c) % 2) + ((r * c) % 3)) % 2 === 0; break;
            case 7: invert = (((r + c) % 2) + ((r * c) % 3)) % 2 === 0; break;
          }
          if (invert) mat[r][c] ^= 1;
        }
      }

      // Write format info bits
      const fmt = qrBchFormat(mask);
      for (let i = 0; i <= 5; i += 1) mat[8][i] = (fmt >>> (14 - i)) & 1;
      mat[8][7] = (fmt >>> 8) & 1;
      mat[8][8] = (fmt >>> 7) & 1;
      mat[7][8] = (fmt >>> 6) & 1;
      for (let i = 0; i <= 5; i += 1) mat[5 - i][8] = (fmt >>> (5 - i)) & 1;

      for (let i = 0; i <= 7; i += 1) mat[8][size - 1 - i] = (fmt >>> i) & 1;
      for (let i = 0; i <= 6; i += 1) mat[size - 7 + i][8] = (fmt >>> (14 - i)) & 1;
      mat[size - 8][8] = 1;
      return mat;
    };

    const penaltyScore = (mat) => {
      let score = 0;
      let darkCount = 0;
      for (let r = 0; r < size; r += 1) {
        let rowRun = 1;
        let colRun = 1;
        for (let c = 0; c < size; c += 1) {
          darkCount += mat[r][c];
          if (c > 0) {
            if (mat[r][c] === mat[r][c - 1]) rowRun += 1;
            else {
              if (rowRun >= 5) score += 3 + (rowRun - 5);
              rowRun = 1;
            }
            if (mat[c][r] === mat[c - 1][r]) colRun += 1;
            else {
              if (colRun >= 5) score += 3 + (colRun - 5);
              colRun = 1;
            }
          }
          if (
            r < size - 1 &&
            c < size - 1 &&
            mat[r][c] === mat[r][c + 1] &&
            mat[r][c] === mat[r + 1][c] &&
            mat[r][c] === mat[r + 1][c + 1]
          ) {
            score += 3;
          }
        }
        if (rowRun >= 5) score += 3 + (rowRun - 5);
        if (colRun >= 5) score += 3 + (colRun - 5);
      }
      const k = Math.floor(Math.abs(darkCount * 20 - size * size * 10) / (size * size));
      score += k * 10;
      return score;
    };

    let bestMat = null;
    let bestScore = Infinity;
    for (let mask = 0; mask < 8; mask += 1) {
      const mat = applyMask(mask);
      const s = penaltyScore(mat);
      if (s < bestScore) {
        bestScore = s;
        bestMat = mat;
      }
    }
    return bestMat;
  }

  function renderQrToCanvas(canvas, text, targetPx = 220) {
    const matrix = generateQrMatrix(text);
    const quietZone = 4;
    const modules = matrix.length + quietZone * 2;
    const scale = Math.max(2, Math.floor(targetPx / modules));
    const dim = modules * scale;
    canvas.width = dim;
    canvas.height = dim;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, dim, dim);
    ctx.fillStyle = '#000000';
    for (let r = 0; r < matrix.length; r += 1) {
      for (let c = 0; c < matrix.length; c += 1) {
        if (matrix[r][c]) {
          ctx.fillRect((c + quietZone) * scale, (r + quietZone) * scale, scale, scale);
        }
      }
    }
  }

  // ---------------------------------------------------------------------------
  // Access Key Storage & Isolated QR Login (never sends browser SESSDATA cookie)
  // ---------------------------------------------------------------------------
  let cachedAccessKey = GM_getValue(STORAGE_KEYS.ACCESS_KEY, '');

  function getAccessKey() {
    return cachedAccessKey;
  }

  function setAccessKey(token) {
    cachedAccessKey = (token || '').trim();
    if (cachedAccessKey) {
      GM_setValue(STORAGE_KEYS.ACCESS_KEY, cachedAccessKey);
    } else {
      GM_deleteValue(STORAGE_KEYS.ACCESS_KEY);
    }
  }

  async function requestLoginQrCode() {
    const buvid = generateBuvid();
    const headers = {
      'Content-Type': 'application/x-www-form-urlencoded; charset=utf-8',
      'User-Agent': APP_UA,
      buvid,
    };
    const baseLoginParams = {
      appkey: LOGIN_APP_KEY,
      build: APP_BUILD,
      c_locale: 'zh-Hans_CN',
      channel: 'website',
      local_id: buvid,
      mobi_app: 'android',
      platform: 'android',
      s_locale: 'zh-Hans_CN',
    };

    const res = await gmRequest({
      method: 'POST',
      url: 'https://passport.bilibili.com/x/passport-tv-login/qrcode/auth_code',
      data: signAppQuery(baseLoginParams, LOGIN_APP_SEC),
      headers,
      anonymous: true,
    });
    const authCode = res.body?.data?.auth_code;
    const qrUrl = res.body?.data?.url;
    if (res.status !== 200 || res.body?.code !== 0 || !authCode || !qrUrl) {
      throw new Error(`申请二维码失败 (code=${res.body?.code ?? res.status})`);
    }
    return { authCode, qrUrl, headers, baseLoginParams };
  }

  async function pollLoginQrCode({ authCode, headers, baseLoginParams }) {
    const res = await gmRequest({
      method: 'POST',
      url: 'https://passport.bilibili.com/x/passport-tv-login/qrcode/poll',
      data: signAppQuery({ ...baseLoginParams, auth_code: authCode }, LOGIN_APP_SEC),
      headers,
      anonymous: true,
    });
    return {
      status: res.status,
      code: res.body?.code,
      message: res.body?.message || '',
      accessToken: res.body?.data?.access_token || '',
    };
  }

  // ---------------------------------------------------------------------------
  // Persistent IP Location Cache (TTL + LRU cap + debounced writes)
  // ---------------------------------------------------------------------------
  const ipCache = new Map();
  let saveCacheTimer = null;

  function loadCache() {
    try {
      const raw = GM_getValue(STORAGE_KEYS.CACHE, null);
      if (!raw || typeof raw !== 'object') return;
      const now = Date.now();
      for (const [uid, entry] of Object.entries(raw)) {
        if (!entry || typeof entry !== 'object') continue;
        const ttl = entry.loc ? CACHE_TTL_FOUND_MS : CACHE_TTL_EMPTY_MS;
        if (now - entry.ts < ttl) {
          ipCache.set(uid, entry);
        }
      }
    } catch {
      // Ignore corrupted cache
    }
  }

  function scheduleCacheSave() {
    if (saveCacheTimer !== null) return;
    saveCacheTimer = setTimeout(() => {
      saveCacheTimer = null;
      try {
        while (ipCache.size > CACHE_MAX_ENTRIES) {
          const oldestKey = ipCache.keys().next().value;
          ipCache.delete(oldestKey);
        }
        GM_setValue(STORAGE_KEYS.CACHE, Object.fromEntries(ipCache));
      } catch {
        // Ignore storage quota errors
      }
    }, 2000);
  }

  function getCachedLocation(uid) {
    const entry = ipCache.get(uid);
    if (!entry) return undefined;
    const ttl = entry.loc ? CACHE_TTL_FOUND_MS : CACHE_TTL_EMPTY_MS;
    if (Date.now() - entry.ts >= ttl) {
      ipCache.delete(uid);
      return undefined;
    }
    // Refresh insertion order for LRU eviction
    ipCache.delete(uid);
    ipCache.set(uid, entry);
    return entry.loc;
  }

  function setCachedLocation(uid, loc) {
    ipCache.delete(uid);
    ipCache.set(uid, { loc: loc || null, ts: Date.now() });
    scheduleCacheSave();
  }

  function clearLocationCache() {
    ipCache.clear();
    GM_deleteValue(STORAGE_KEYS.CACHE);
  }

  loadCache();

  // ---------------------------------------------------------------------------
  // Rate-Limited Priority Request Queue & Bilibili API Clients
  // ---------------------------------------------------------------------------
  const inFlightIpRequests = new Map();
  const inFlightRoomLookups = new Map();
  const requestQueue = [];
  let activeCount = 0;
  let lastDispatchTs = 0;
  let backoffUntilTs = 0;
  let consecutiveRateLimits = 0;
  let tokenInvalidNotified = false;

  function enqueueTask(taskFn, highPriority = false) {
    return new Promise((resolve, reject) => {
      const item = { taskFn, resolve, reject };
      if (highPriority) {
        requestQueue.unshift(item);
      } else {
        requestQueue.push(item);
      }
      pumpQueue();
    });
  }

  function pumpQueue() {
    if (activeCount >= MAX_CONCURRENCY || requestQueue.length === 0) return;

    const now = Date.now();
    const earliest = Math.max(backoffUntilTs, lastDispatchTs + MIN_DISPATCH_INTERVAL_MS);
    if (now < earliest) {
      setTimeout(pumpQueue, earliest - now + 10);
      return;
    }

    const item = requestQueue.shift();
    if (!item) return;

    activeCount += 1;
    lastDispatchTs = Date.now();

    Promise.resolve()
      .then(() => item.taskFn())
      .then(item.resolve, item.reject)
      .finally(() => {
        activeCount -= 1;
        pumpQueue();
      });

    if (activeCount < MAX_CONCURRENCY && requestQueue.length > 0) {
      setTimeout(pumpQueue, MIN_DISPATCH_INTERVAL_MS);
    }
  }

  function formatCompactLocation(rawLocation) {
    if (!rawLocation) return '';
    return rawLocation.replace(/^IP属地[：:\s]*/i, '').trim() || rawLocation;
  }

  function formatFullLocation(rawLocation) {
    if (!rawLocation) return '';
    const compact = formatCompactLocation(rawLocation);
    return `IP属地：${compact}`;
  }

  function extractLocationFromSpaceResponse(spaceResponse) {
    const card = spaceResponse?.data?.card;
    if (!card || typeof card !== 'object') return null;

    const tags = [
      ...(Array.isArray(card.space_tag) ? card.space_tag : []),
      ...(Array.isArray(card.space_tag_bottom) ? card.space_tag_bottom : []),
    ];

    for (const tag of tags) {
      if (tag && tag.type === 'location' && typeof tag.title === 'string' && tag.title.trim()) {
        return tag.title.trim();
      }
    }
    return null;
  }

  async function fetchIpLocationByUid(uid, { highPriority = false } = {}) {
    const uidStr = String(uid || '').trim();
    if (!/^\d+$/.test(uidStr)) return null;

    const cached = getCachedLocation(uidStr);
    if (cached !== undefined) return cached;

    const accessKey = getAccessKey();
    if (!accessKey) return null;

    if (inFlightIpRequests.has(uidStr)) {
      return inFlightIpRequests.get(uidStr);
    }

    const promise = enqueueTask(async () => {
      const query = signAppQuery({
        access_key: accessKey,
        appkey: APP_KEY,
        build: APP_BUILD,
        mobi_app: 'android',
        platform: 'android',
        vmid: uidStr,
      });

      const res = await gmRequest({
        method: 'GET',
        url: `https://app.bilibili.com/x/v2/space?${query}`,
        headers: { 'User-Agent': APP_UA },
        anonymous: true,
      });

      const code = res.body?.code;

      // Handle rate limiting with exponential backoff
      if (res.status === 412 || code === -412 || code === -509 || code === -799) {
        consecutiveRateLimits += 1;
        const delayMs = Math.min(30000, 3000 * 2 ** (consecutiveRateLimits - 1));
        backoffUntilTs = Date.now() + delayMs;
        console.warn(`${LOG_PREFIX} 触发限流 (code=${code ?? res.status})，暂停 ${delayMs}ms`);
        return null;
      }

      consecutiveRateLimits = 0;

      // Handle expired/invalid access_key
      if (code === -101 || code === -2) {
        if (!tokenInvalidNotified) {
          tokenInvalidNotified = true;
          console.warn(`${LOG_PREFIX} Access Key 已失效 (code=${code})，请重新获取`);
          showSetupBanner('Access Key 已过期，请重新获取以继续显示 IP 属地', { force: true });
        }
        return null;
      }

      if (code !== 0) {
        console.warn(`${LOG_PREFIX} 查询 uid=${uidStr} 失败:`, res.body?.message || code);
        return null;
      }

      const loc = extractLocationFromSpaceResponse(res.body);
      setCachedLocation(uidStr, loc);
      return loc;
    }, highPriority)
      .catch((err) => {
        console.warn(`${LOG_PREFIX} 查询 uid=${uidStr} 异常:`, err);
        return null;
      })
      .finally(() => {
        inFlightIpRequests.delete(uidStr);
      });

    inFlightIpRequests.set(uidStr, promise);
    return promise;
  }

  async function resolveUidByRoomId(roomId, { highPriority = false } = {}) {
    const roomStr = String(roomId || '').trim();
    if (!/^\d+$/.test(roomStr)) return null;

    if (roomToUidMap.has(roomStr)) {
      return roomToUidMap.get(roomStr);
    }

    if (inFlightRoomLookups.has(roomStr)) {
      return inFlightRoomLookups.get(roomStr);
    }

    const promise = enqueueTask(async () => {
      const res = await gmRequest({
        method: 'GET',
        url: `https://api.live.bilibili.com/room/v1/Room/get_info?room_id=${encodeURIComponent(roomStr)}`,
        headers: { Referer: 'https://live.bilibili.com/' },
        anonymous: true,
      });

      const uid = res.body?.data?.uid;
      if (res.body?.code === 0 && uid) {
        const uidStr = String(uid);
        roomToUidMap.set(roomStr, uidStr);
        if (res.body.data.room_id) {
          roomToUidMap.set(String(res.body.data.room_id), uidStr);
        }
        if (res.body.data.short_id) {
          roomToUidMap.set(String(res.body.data.short_id), uidStr);
        }
        return uidStr;
      }
      return null;
    }, highPriority)
      .catch(() => null)
      .finally(() => {
        inFlightRoomLookups.delete(roomStr);
      });

    inFlightRoomLookups.set(roomStr, promise);
    return promise;
  }

