  // ---------------------------------------------------------------------------
  // Setup Banner & Native <dialog> QR Login Modal
  // ---------------------------------------------------------------------------
  let bannerElement = null;
  let qrDialogElement = null;
  let qrPollTimer = null;

  function removeSetupBanner() {
    if (bannerElement && bannerElement.isConnected) {
      bannerElement.remove();
    }
    bannerElement = null;
  }

  function stopQrPolling() {
    if (qrPollTimer !== null) {
      clearInterval(qrPollTimer);
      qrPollTimer = null;
    }
  }

  function openQrLoginDialog() {
    if (!document.body) return;

    stopQrPolling();
    if (qrDialogElement && qrDialogElement.isConnected) {
      if (qrDialogElement.open) qrDialogElement.close();
      qrDialogElement.remove();
    }

    const dialog = document.createElement('dialog');
    dialog.id = 'bili-live-ip-qr-dialog';
    dialog.setAttribute('closedby', 'any');
    dialog.setAttribute('aria-labelledby', 'bili-live-ip-qr-title');

    const body = document.createElement('div');
    body.className = 'bili-ip-qr-body';

    const title = document.createElement('h1');
    title.id = 'bili-live-ip-qr-title';
    title.textContent = '扫码获取 Access Key';

    const subtitle = document.createElement('p');
    subtitle.className = 'bili-ip-qr-sub';
    subtitle.textContent =
      '请使用手机「哔哩哔哩 App」扫码授权。全程采用独立设备令牌，不触碰浏览器 Cookie，不会导致网页账号退出登录。';

    const frame = document.createElement('div');
    frame.className = 'bili-ip-qr-frame';

    const canvas = document.createElement('canvas');
    frame.appendChild(canvas);

    const statusText = document.createElement('p');
    statusText.className = 'bili-ip-qr-status';
    statusText.textContent = '正在申请登录二维码...';

    const actions = document.createElement('form');
    actions.method = 'dialog';
    actions.className = 'bili-ip-qr-actions';

    const refreshBtn = document.createElement('button');
    refreshBtn.type = 'button';
    refreshBtn.className = 'bili-ip-qr-refresh';
    refreshBtn.textContent = '刷新二维码';

    const closeBtn = document.createElement('button');
    closeBtn.type = 'submit';
    closeBtn.value = 'cancel';
    closeBtn.className = 'bili-ip-qr-cancel';
    closeBtn.autofocus = true;
    closeBtn.textContent = '关闭';

    actions.replaceChildren(refreshBtn, closeBtn);
    body.replaceChildren(title, subtitle, frame, statusText, actions);
    dialog.appendChild(body);
    document.body.appendChild(dialog);
    qrDialogElement = dialog;

    // Fallback light-dismiss for browsers without native <dialog closedby="any">
    if (!('closedBy' in HTMLDialogElement.prototype)) {
      const isOutside = (e) => {
        const r = dialog.getBoundingClientRect();
        return e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom;
      };
      let pressedOutside = false;
      dialog.addEventListener('pointerdown', (e) => {
        pressedOutside = isOutside(e);
      });
      dialog.addEventListener('pointerup', (e) => {
        if (pressedOutside && isOutside(e)) dialog.close();
      });
    }

    dialog.addEventListener('close', () => {
      stopQrPolling();
      dialog.returnValue = '';
      dialog.remove();
      if (qrDialogElement === dialog) qrDialogElement = null;
    });

    let activeSession = 0;

    async function startQrFlow() {
      const sessionId = ++activeSession;
      stopQrPolling();
      refreshBtn.disabled = true;
      statusText.textContent = '正在申请登录二维码...';

      try {
        const qrData = await requestLoginQrCode();
        if (sessionId !== activeSession || !dialog.open) return;

        renderQrToCanvas(canvas, qrData.qrUrl, 220);
        statusText.textContent = '请使用手机 B 站 App 扫描二维码';
        refreshBtn.disabled = false;

        let polling = false;
        qrPollTimer = setInterval(async () => {
          if (polling || sessionId !== activeSession || !dialog.open) return;
          polling = true;
          try {
            const result = await pollLoginQrCode(qrData);
            if (sessionId !== activeSession || !dialog.open) return;

            if (result.code === 0 && result.accessToken) {
              stopQrPolling();
              setAccessKey(result.accessToken);
              tokenInvalidNotified = false;
              statusText.textContent = '✅ 授权成功！正在加载主播 IP 属地...';
              removeSetupBanner();
              refreshCurrentPage();
              setTimeout(() => {
                if (dialog.open) dialog.close('success');
              }, 800);
            } else if (result.code === 86090) {
              statusText.textContent = '📱 已扫码，请在手机上点击「确认登录」';
            } else if (result.code === 86038) {
              stopQrPolling();
              statusText.textContent = '⏰ 二维码已过期，请点击「刷新二维码」';
            } else if (result.code !== 86039) {
              statusText.textContent = `状态异常 (code=${result.code ?? result.status})`;
            }
          } catch (err) {
            console.warn(`${LOG_PREFIX} 轮询扫码状态异常:`, err);
          } finally {
            polling = false;
          }
        }, 2500);
      } catch (err) {
        if (sessionId !== activeSession || !dialog.open) return;
        console.error(`${LOG_PREFIX} 申请二维码失败:`, err);
        statusText.textContent = `❌ ${err.message}`;
        refreshBtn.disabled = false;
      }
    }

    refreshBtn.addEventListener('click', startQrFlow);

    dialog.showModal();
    startQrFlow();
  }

  function showSetupBanner(
    message = '需要扫码获取 Access Key 才能显示主播 IP 属地',
    { force = false } = {}
  ) {
    // Show only in top-level window to avoid duplicate banners inside themed room iframes
    if (window.top !== window) return;
    if (sessionStorage.getItem(STORAGE_KEYS.BANNER_DISMISSED) === '1' && !force && !tokenInvalidNotified) {
      return;
    }
    if (!document.body) return;

    // Avoid recreating the banner on DOM mutations while it is already mounted
    if (bannerElement && bannerElement.isConnected) {
      if (!force) return;
      removeSetupBanner();
    }

    const banner = document.createElement('div');
    banner.id = 'bili-live-ip-setup-banner';

    const label = document.createElement('span');
    label.textContent = `📍 ${message}`;

    const actionBtn = document.createElement('button');
    actionBtn.type = 'button';
    actionBtn.className = 'bili-ip-btn-primary';
    actionBtn.textContent = '扫码获取';

    const closeBtn = document.createElement('button');
    closeBtn.type = 'button';
    closeBtn.className = 'bili-ip-btn-close';
    closeBtn.title = '本次会话不再提示';
    closeBtn.textContent = '×';

    actionBtn.addEventListener('click', () => {
      openQrLoginDialog();
    });

    closeBtn.addEventListener('click', () => {
      sessionStorage.setItem(STORAGE_KEYS.BANNER_DISMISSED, '1');
      removeSetupBanner();
    });

    banner.replaceChildren(label, actionBtn, closeBtn);
    document.body.appendChild(banner);
    bannerElement = banner;
  }

  // ---------------------------------------------------------------------------
  // Page Route & Room ID Helpers
  // ---------------------------------------------------------------------------
  function getRoomIdFromPath(pathname = window.location.pathname) {
    const match = pathname.match(/^\/(?:blanc\/)?(\d+)(?:\/|$)/);
    return match ? match[1] : null;
  }

  function extractRoomIdFromHref(href) {
    if (!href) return null;
    try {
      const parsed = new URL(href, window.location.origin);
      if (parsed.hostname !== 'live.bilibili.com') return null;
      return getRoomIdFromPath(parsed.pathname);
    } catch {
      return null;
    }
  }

  function getRoomAnchorUidFromGlobals() {
    const neptune = PAGE_WINDOW.__NEPTUNE_IS_MY_WAIFU__;
    const uid =
      neptune?.roomInfoRes?.data?.room_info?.uid ??
      neptune?.roomInitRes?.data?.uid ??
      PAGE_WINDOW.BilibiliLive?.UID ??
      null;
    if (uid && /^\d+$/.test(String(uid))) {
      return String(uid);
    }
    return null;
  }

  function extractUidFromCardElement(cardEl) {
    // 1. Vue 2 component on live-region (/p/eden/area-tags, /all, /area/*, /lol, /show/*)
    const vue2Candidates = [cardEl?.__vue__, cardEl?.parentElement?.__vue__];
    for (const vm of vue2Candidates) {
      if (!vm) continue;
      const uid =
        vm.anchorId ??
        vm.uid ??
        vm.$props?.anchorId ??
        vm.$attrs?.anchorId ??
        vm.roomCardInfo?.uid;
      if (uid && /^\d+$/.test(String(uid))) {
        return String(uid);
      }
    }

    // 2. Vue 3 component on live.bilibili.com homepage (.room-card-ctnr)
    const v3 = cardEl?.__vueParentComponent || cardEl?.parentElement?.__vueParentComponent;
    if (v3) {
      const uid =
        v3.props?.roomCardInfo?.anchorUid ??
        v3.props?.roomCardInfo?.uid ??
        v3.props?.anchorId ??
        v3.ctx?.anchorUid ??
        v3.ctx?.roomCardInfo?.anchorUid ??
        v3.ctx?.roomCardInfo?.uid ??
        v3.setupState?.anchorUid;
      if (uid && /^\d+$/.test(String(uid))) {
        return String(uid);
      }
    }

    // 3. Space link inside card (if any)
    const spaceLink = cardEl.querySelector?.('a[href*="space.bilibili.com/"]');
    if (spaceLink) {
      const m = spaceLink.href.match(/space\.bilibili\.com\/(\d+)/);
      if (m) return m[1];
    }

    return null;
  }

  function extractRoomIdFromCardElement(cardEl) {
    if (cardEl.tagName === 'A' && cardEl.href) {
      const id = extractRoomIdFromHref(cardEl.href);
      if (id) return id;
    }

    const nestedLink = cardEl.querySelector?.('a[href*="live.bilibili.com/"], a[href^="/"]');
    if (nestedLink?.href) {
      const id = extractRoomIdFromHref(nestedLink.href);
      if (id) return id;
    }

    const vm = cardEl?.__vue__ || cardEl?.parentElement?.__vue__;
    const vueRoomId = vm?.roomId ?? vm?.$props?.roomId ?? vm?.$attrs?.roomId;
    if (vueRoomId && /^\d+$/.test(String(vueRoomId))) {
      return String(vueRoomId);
    }

    const v3 = cardEl?.__vueParentComponent || cardEl?.parentElement?.__vueParentComponent;
    const v3RoomId =
      v3?.props?.roomCardInfo?.roomId ??
      v3?.props?.roomCardInfo?.roomid ??
      v3?.ctx?.roomId;
    if (v3RoomId && /^\d+$/.test(String(v3RoomId))) {
      return String(v3RoomId);
    }

    return null;
  }

  // ---------------------------------------------------------------------------
  // Live Room Page Handler
  // ---------------------------------------------------------------------------
  let currentRoomUid = null;
  let roomBadgeRenderToken = 0;

  function findRoomHeaderAnchorTarget() {
    const header = document.querySelector('#head-info-vm');
    if (!header) return null;

    // 2026 live room header (layout v2 - live)
    const liveUsername = header.querySelector('.live-profile .anchor-username');
    if (liveUsername) return { target: liveUsername, mode: 'after' };

    // 2026 live room header (layout v2 - offline / closedown)
    const offlineUsername = header.querySelector('.closedown-profile .initiator-name');
    if (offlineUsername) return { target: offlineUsername, mode: 'after' };

    // Legacy / themed live room header fallback
    const legacyUsername = header.querySelector('.room-owner-username');
    if (legacyUsername) return { target: legacyUsername, mode: 'after' };

    const upperLeft = header.querySelector('.rows-ctnr .upper-row .left-ctnr');
    if (upperLeft) return { target: upperLeft, mode: 'append' };

    const spaceAnchor = header.querySelector('a[href*="space.bilibili.com/"]');
    if (spaceAnchor) return { target: spaceAnchor, mode: 'after' };

    return null;
  }

  function renderRoomBadge(text, { loading = false, tooltip = '' } = {}) {
    const header = document.querySelector('#head-info-vm');
    if (!header) return false;

    const mount = findRoomHeaderAnchorTarget();
    if (!mount) return false;

    let badge = header.querySelector(`[${ROOM_BADGE_ATTR}]`);
    if (!badge) {
      badge = document.createElement('span');
      badge.setAttribute(ROOM_BADGE_ATTR, '1');
      if (mount.mode === 'after') {
        mount.target.insertAdjacentElement('afterend', badge);
      } else {
        mount.target.appendChild(badge);
      }
    } else if (mount.mode === 'after' && badge.previousElementSibling !== mount.target) {
      mount.target.insertAdjacentElement('afterend', badge);
    }

    badge.className = `${BADGE_CLASS} ${BADGE_CLASS}--room${loading ? ` ${BADGE_CLASS}--loading` : ''}`;
    badge.title = tooltip || text;
    badge.replaceChildren(text);
    return true;
  }

  function removeRoomBadge() {
    const badge = document.querySelector(`#head-info-vm [${ROOM_BADGE_ATTR}]`);
    if (badge) badge.remove();
  }

  async function processLiveRoomPage() {
    const roomId = getRoomIdFromPath();
    if (!roomId) return;

    if (!getAccessKey()) {
      showSetupBanner();
      return;
    }

    const token = ++roomBadgeRenderToken;
    const uid = getRoomAnchorUidFromGlobals() || (await resolveUidByRoomId(roomId, { highPriority: true }));
    if (token !== roomBadgeRenderToken || !uid) return;

    currentRoomUid = uid;
    const cached = getCachedLocation(uid);
    if (cached !== undefined) {
      if (cached) {
        renderRoomBadge(`📍 ${formatFullLocation(cached)}`, { tooltip: formatFullLocation(cached) });
      } else {
        removeRoomBadge();
      }
      return;
    }

    renderRoomBadge('📍 IP属地查询中...', { loading: true });
    const location = await fetchIpLocationByUid(uid, { highPriority: true });
    if (token !== roomBadgeRenderToken) return;

    if (location) {
      renderRoomBadge(`📍 ${formatFullLocation(location)}`, { tooltip: formatFullLocation(location) });
    } else {
      removeRoomBadge();
    }
  }

  function ensureRoomBadgeMounted() {
    if (!currentRoomUid || !getAccessKey()) return;
    const cached = getCachedLocation(currentRoomUid);
    if (cached) {
      renderRoomBadge(`📍 ${formatFullLocation(cached)}`, { tooltip: formatFullLocation(cached) });
    }
  }

  // ---------------------------------------------------------------------------
  // Listing Cards Handler (Area Tags / All / Area / LOL / Home / Recommendations)
  // ---------------------------------------------------------------------------
  const CARD_SELECTORS = [
    'a[class*="Item_card-item_"]', // live-region SPA (/p/eden/area-tags, /all, /area/*, /lol)
    'a.room-card-ctnr', // live.bilibili.com homepage
    '.room-card-wrapper > a[href]', // generic room card wrapper
  ].join(', ');

  let cardPositionMode = GM_getValue(STORAGE_KEYS.CARD_POSITION, 'cover'); // 'cover' | 'inline'
  const observedCards = new WeakSet();

  const cardIntersectionObserver = new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        if (!entry.isIntersecting) continue;
        const cardEl = entry.target;
        cardIntersectionObserver.unobserve(cardEl);
        hydrateCardIpBadge(cardEl);
      }
    },
    { rootMargin: '220px 0px' }
  );

  function findCardBadgeMount(cardEl) {
    if (cardPositionMode === 'inline') {
      const nick =
        cardEl.querySelector('[class*="Item_nickName_"]') ||
        cardEl.querySelector('.room-anchor > span') ||
        cardEl.querySelector('.room-card-info .uname') ||
        cardEl.querySelector('[class*="nickName"]');
      if (nick) {
        return { container: nick, mode: 'after', variant: 'inline' };
      }
    }

    // Default: bottom-left overlay on the cover image container
    const cover =
      cardEl.querySelector('[class*="Item_cover-wrap_"]') ||
      cardEl.querySelector('.cover-wrapper') ||
      cardEl.querySelector('.cover-ctnr') ||
      cardEl.querySelector('[class*="cover-wrap"]');
    if (cover) {
      const computedPos = window.getComputedStyle(cover).position;
      if (computedPos === 'static') {
        cover.style.position = 'relative';
      }
      return { container: cover, mode: 'append', variant: 'cover' };
    }

    // Fallback to inline beside nickname
    const nickFallback = cardEl.querySelector('[class*="Item_nickName_"]');
    if (nickFallback) {
      return { container: nickFallback, mode: 'after', variant: 'inline' };
    }

    return null;
  }

  function renderCardBadge(cardEl, rawLocation) {
    const existing = cardEl.querySelector(`[${CARD_BADGE_ATTR}]`);
    if (!rawLocation) {
      if (existing) existing.remove();
      return;
    }

    const mount = findCardBadgeMount(cardEl);
    if (!mount) return;

    const badge = existing || document.createElement('span');
    badge.setAttribute(CARD_BADGE_ATTR, '1');
    badge.className = `${BADGE_CLASS} ${BADGE_CLASS}--${mount.variant}`;
    badge.title = formatFullLocation(rawLocation);
    badge.replaceChildren(`📍 ${formatCompactLocation(rawLocation)}`);

    if (!existing || !badge.isConnected) {
      if (mount.mode === 'after') {
        mount.container.insertAdjacentElement('afterend', badge);
      } else {
        mount.container.appendChild(badge);
      }
    }
  }

  function getCardIdentity(cardEl) {
    const uid = extractUidFromCardElement(cardEl);
    const roomId = extractRoomIdFromCardElement(cardEl);
    return {
      uid,
      roomId,
      key: uid ? `u:${uid}` : roomId ? `r:${roomId}` : '',
    };
  }

  async function hydrateCardIpBadge(cardEl) {
    if (!cardEl.isConnected || !getAccessKey()) return;

    const { uid: directUid, roomId, key } = getCardIdentity(cardEl);
    if (!key) return;

    cardEl.dataset.biliIpKey = key;

    let uid = directUid;
    if (!uid && roomId) {
      uid = roomToUidMap.get(roomId) || (await resolveUidByRoomId(roomId));
    }
    if (!uid || !cardEl.isConnected || cardEl.dataset.biliIpKey !== key) return;

    const location = await fetchIpLocationByUid(uid, { highPriority: false });
    if (!cardEl.isConnected || cardEl.dataset.biliIpKey !== key) return;

    renderCardBadge(cardEl, location);
  }

  function scanListingCards(root = document) {
    if (!getAccessKey()) return;
    const cards = root.querySelectorAll(CARD_SELECTORS);
    for (const cardEl of cards) {
      const { key } = getCardIdentity(cardEl);
      if (!key) continue;

      const prevKey = cardEl.dataset.biliIpKey;
      if (prevKey && prevKey !== key) {
        // Vue reused this DOM element for a different streamer
        const oldBadge = cardEl.querySelector(`[${CARD_BADGE_ATTR}]`);
        if (oldBadge) oldBadge.remove();
        cardEl.dataset.biliIpKey = key;
        cardIntersectionObserver.observe(cardEl);
        continue;
      }

      if (!observedCards.has(cardEl)) {
        observedCards.add(cardEl);
        cardEl.dataset.biliIpKey = key;
        cardIntersectionObserver.observe(cardEl);
      } else if (prevKey === key && !cardEl.querySelector(`[${CARD_BADGE_ATTR}]`)) {
        // Re-check if location is already cached (e.g., after token acquisition)
        const { uid } = getCardIdentity(cardEl);
        if (uid) {
          const cached = getCachedLocation(uid);
          if (cached) renderCardBadge(cardEl, cached);
        }
      }
    }
  }

  // ---------------------------------------------------------------------------
  // Lifecycle, MutationObserver & SPA Navigation Coordination
  // ---------------------------------------------------------------------------
  let scanScheduled = false;
  let lastHref = window.location.href;

  function scheduleScan() {
    if (scanScheduled) return;
    scanScheduled = true;
    requestAnimationFrame(() => {
      scanScheduled = false;
      if (!getAccessKey()) {
        if (!bannerElement || !bannerElement.isConnected) {
          showSetupBanner();
        }
        return;
      }
      if (getRoomIdFromPath()) {
        if (!document.querySelector(`#head-info-vm [${ROOM_BADGE_ATTR}]`)) {
          if (currentRoomUid) {
            ensureRoomBadgeMounted();
          } else {
            processLiveRoomPage();
          }
        }
      }
      scanListingCards(document);
    });
  }

  function refreshCurrentPage() {
    // Clear existing card keys so cards re-hydrate cleanly
    for (const badge of document.querySelectorAll(`[${CARD_BADGE_ATTR}]`)) {
      badge.remove();
    }
    for (const cardEl of document.querySelectorAll(CARD_SELECTORS)) {
      delete cardEl.dataset.biliIpKey;
      cardIntersectionObserver.observe(cardEl);
    }

    currentRoomUid = null;
    if (getRoomIdFromPath()) {
      processLiveRoomPage();
    }
    scanListingCards(document);
  }

  function handleUrlChange() {
    if (window.location.href === lastHref) return;
    lastHref = window.location.href;
    currentRoomUid = null;
    removeRoomBadge();
    setTimeout(() => {
      if (getRoomIdFromPath()) {
        processLiveRoomPage();
      }
      scanListingCards(document);
    }, 250);
  }

  function installHistoryHooks() {
    const origPushState = history.pushState;
    const origReplaceState = history.replaceState;

    history.pushState = function hookedPushState(...args) {
      const result = origPushState.apply(this, args);
      handleUrlChange();
      return result;
    };

    history.replaceState = function hookedReplaceState(...args) {
      const result = origReplaceState.apply(this, args);
      handleUrlChange();
      return result;
    };

    window.addEventListener('popstate', handleUrlChange);
  }

  // ---------------------------------------------------------------------------
  // Tampermonkey Menu Commands
  // ---------------------------------------------------------------------------
  function registerMenuCommands() {
    const hasKey = Boolean(getAccessKey());

    GM_registerMenuCommand(
      `${hasKey ? '✅ 已配置' : '🔑 未配置'} — 扫码获取 Access Key（不掉网页登录）`,
      () => {
        openQrLoginDialog();
      }
    );

    GM_registerMenuCommand('✏️ 手动设置 Access Key', () => {
      const current = getAccessKey();
      const masked = current ? `${current.slice(0, 4)}****${current.slice(-4)}` : '未设置';
      const input = window.prompt(`请输入 B 站移动端 Access Key（当前：${masked}）：`, '');
      if (input === null) return;
      const trimmed = input.trim();
      if (!trimmed) {
        alert('输入为空，未修改。');
        return;
      }
      setAccessKey(trimmed);
      tokenInvalidNotified = false;
      removeSetupBanner();
      refreshCurrentPage();
    });

    GM_registerMenuCommand('🗑️ 清除 Access Key', () => {
      setAccessKey('');
      alert('已清除 Access Key。');
    });

    GM_registerMenuCommand('🧹 清除 IP 属地缓存', () => {
      clearLocationCache();
      refreshCurrentPage();
      alert('已清除本地 IP 属地缓存并重新查询。');
    });

    GM_registerMenuCommand(
      `🏷️ 切换卡片显示位置（当前：${cardPositionMode === 'cover' ? '封面左下角' : '昵称旁'}）`,
      () => {
        cardPositionMode = cardPositionMode === 'cover' ? 'inline' : 'cover';
        GM_setValue(STORAGE_KEYS.CARD_POSITION, cardPositionMode);
        refreshCurrentPage();
        alert(
          `卡片 IP 属地位置已切换为：${cardPositionMode === 'cover' ? '封面左下角' : '昵称旁'}`
