      }
    );
  }

  // ---------------------------------------------------------------------------
  // Bootstrap
  // ---------------------------------------------------------------------------
  function isOwnElement(node) {
    if (!(node instanceof Element)) return false;
    return (
      node.id === 'bili-live-ip-setup-banner' ||
      node.id === 'bili-live-ip-qr-dialog' ||
      node.classList.contains(BADGE_CLASS) ||
      Boolean(node.closest('#bili-live-ip-setup-banner, #bili-live-ip-qr-dialog'))
    );
  }

  function installAccessKeySyncListener() {
    if (typeof GM_addValueChangeListener !== 'function') return;
    GM_addValueChangeListener(STORAGE_KEYS.ACCESS_KEY, (_name, _oldVal, newVal) => {
      cachedAccessKey = (newVal || '').trim();
      tokenInvalidNotified = false;
      if (cachedAccessKey) {
        removeSetupBanner();
        refreshCurrentPage();
      }
    });
  }

  function init() {
    injectStyles();
    registerMenuCommands();
    installHistoryHooks();
    installAccessKeySyncListener();

    if (!getAccessKey()) {
      showSetupBanner();
    } else if (getRoomIdFromPath()) {
      processLiveRoomPage();
    }

    scanListingCards(document);

    const observer = new MutationObserver((mutations) => {
      for (const m of mutations) {
        if (isOwnElement(m.target)) continue;
        if (m.type === 'childList' && m.addedNodes.length > 0) {
          let hasExternalNode = false;
          for (const node of m.addedNodes) {
            if (!isOwnElement(node)) {
              hasExternalNode = true;
              break;
            }
          }
          if (hasExternalNode) {
            scheduleScan();
            return;
          }
        }
        if (m.type === 'attributes' && m.attributeName === 'href') {
          scheduleScan();
          return;
        }
      }
    });

    observer.observe(document.body, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ['href'],
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init, { once: true });
  } else {
    init();
  }
})();

