@media (max-width:640px){.g-scene{padding:22px 16px}.g-field{font-size:15px;padding:0 10px}.g-field.g-body{font-size:13px}}
`);

/** 演示里那只鼠标的箭头。 */
function guideArrow() {
  const ns = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(ns, 'svg');
  svg.setAttribute('viewBox', '0 0 22 22');
  svg.setAttribute('width', '22');
  svg.setAttribute('height', '22');
  const p = document.createElementNS(ns, 'path');
  p.setAttribute('d', 'M4 3 L4 18 L8 14.2 L10.8 20 L13.4 18.8 L10.7 13.2 L16 13.2 Z');
  p.setAttribute('fill', '#111');
  p.setAttribute('stroke', '#fff');
  p.setAttribute('stroke-width', '1.4');
  p.setAttribute('stroke-linejoin', 'round');
  svg.append(p);
  return svg;
}

