(() => {
    'use strict';

    const ROOT_SELECTOR = '#task-statement, .task-statement';
    const MARK = 'data-ac-sequence-kind';
    const STYLE_ID = 'ac-sequence-highlight-style';

    // 配列の上側を優先します。否定を含む句 → 長い句 → 単独の用語の順。
    // 色は表記に対する目印です。個別の問題の定義・否定・追加条件を優先してください。
    const RULES = [
        {
            kind: 'check',
            pattern: /(?:非連続|不連続|(?:必ずしも\s*)?連続(?:ではない|でない|しない|していない|とは限らない|でなくてもよい|である必要(?:は|が)?ない))\s*[)）]?\s*(?:な|の)?\s*部分(?:文字列|配列|列)|\b(?:not\s+(?:necessarily\s+)?|non[\s‐‑–-]*)(?:contiguous|consecutive|continuous)[\s‐‑–-]*\)?\s*sub[\s‐‑–-]*(?:sequences?|strings?|arrays?)\b/gi,
        },
        {
            kind: 'contiguous',
            pattern: /連続(?:した|する|している|な|の)?\s*部分(?:文字列|配列|列)|\b(?:contiguous|consecutive|continuous)[\s‐‑–-]+sub[\s‐‑–-]*(?:sequences?|strings?|arrays?)\b/gi,
        },
        {
            kind: 'contiguous',
            pattern: /部分文字列|部分配列|\bsub[\s‐‑–-]*(?:strings?|arrays?)\b/gi,
        },
        {
            kind: 'subsequence',
            pattern: /部分列|\bsub[\s‐‑–-]*sequences?\b/gi,
        },
    ];

    const HELP = {
        contiguous: '通常の意味：連続した区間を取り出す。途中を飛ばさない。問題中の定義・条件を優先。',
        subsequence: '通常の意味：順序を保って選ぶ。途中を飛ばしてもよい（連続していてもよい）。問題中の定義・条件を優先。',
        check: '連続性についての否定・条件を含む表記です。「連続でない」と「連続でなくてもよい」等を区別し、定義を確認。',
    };

    // 数式・入力例・ソースコード・編集欄には触れません。
    const SKIP = [
        'script', 'style', 'noscript', 'textarea', 'input', 'select', 'button',
        'pre', 'code', 'kbd', 'samp', 'var', 'svg', 'math', 'mjx-container',
        '.MathJax', '.MathJax_Display', '.MathJax_Preview', '.katex',
        '[contenteditable]:not([contenteditable="false"])',
    ].join(',');
    const BLOCKS = new Set([
        'ADDRESS', 'ARTICLE', 'ASIDE', 'BLOCKQUOTE', 'BR', 'DD', 'DETAILS',
        'DIV', 'DL', 'DT', 'FIELDSET', 'FIGCAPTION', 'FIGURE', 'FOOTER',
        'H1', 'H2', 'H3', 'H4', 'H5', 'H6', 'HEADER', 'HR', 'LI', 'MAIN',
        'NAV', 'OL', 'P', 'SECTION', 'SUMMARY', 'TABLE', 'TBODY', 'TD',
        'TH', 'THEAD', 'TR', 'UL',
    ]);

    function findMatches(text) {
        const candidates = [];
        RULES.forEach(({ kind, pattern }, priority) => {
            pattern.lastIndex = 0;
            for (const match of text.matchAll(pattern)) {
                candidates.push({ start: match.index, end: match.index + match[0].length, kind, priority });
            }
        });
        // 同じ開始位置なら優先ルール、次いで長い表記を採用。内側の短い語は二重に処理しない。
        candidates.sort((a, b) => a.start - b.start || a.priority - b.priority || b.end - a.end);
        const matches = [];
        let end = 0;
        for (const candidate of candidates) {
            if (candidate.start < end) continue;
            matches.push(candidate);
            end = candidate.end;
        }
        return matches;
    }

    function collectRuns(root) {
        const runs = [];
        let text = '';
        let nodes = [];
        function flush() {
            if (text) runs.push({ text, nodes });
            text = '';
            nodes = [];
        }
        function visit(node) {
            if (node.nodeType === Node.TEXT_NODE) {
                const start = text.length;
                text += node.data;
                nodes.push({ node, start, end: text.length });
                return;
            }
            if (node.nodeType !== Node.ELEMENT_NODE) return;
            if (node.matches(SKIP)) {
                flush();
                return;
            }
            const boundary = BLOCKS.has(node.tagName);
            if (boundary) flush();
            for (const child of node.childNodes) visit(child);
            if (boundary) flush();
        }
        visit(root);
        flush();
        return runs;
    }

    function highlight(root) {
        // 再走査時はこのスクリプト自身の印だけを取り外す。元の強調・リンクは保持。
        for (const mark of root.querySelectorAll(`mark[${MARK}]`)) {
            mark.replaceWith(...mark.childNodes);
        }
        const found = new Set();
        for (const run of collectRuns(root)) {
            // 後ろから処理して、splitText によって手前のオフセットがずれるのを防ぐ。
            for (const match of findMatches(run.text).reverse()) {
                found.add(match.kind);
                for (let i = run.nodes.length - 1; i >= 0; i -= 1) {
                    const entry = run.nodes[i];
                    const start = Math.max(match.start, entry.start);
                    const end = Math.min(match.end, entry.end);
                    if (start >= end) continue;
                    const offset = start - entry.start;
                    const selected = offset > 0 ? entry.node.splitText(offset) : entry.node;
                    if (end - start < selected.length) selected.splitText(end - start);
                    const mark = document.createElement('mark');
                    mark.setAttribute(MARK, match.kind);
                    mark.title = HELP[match.kind];
                    selected.replaceWith(mark);
                    mark.append(selected);
                }
            }
        }
        return found;
    }

    function installStyle() {
        if (document.getElementById(STYLE_ID)) return;
        const style = document.createElement('style');
        style.id = STYLE_ID;
        style.textContent = `
            mark[${MARK}] {
                color: #17212b !important;
                font-weight: 700;
                padding: .06em .16em;
                border-radius: .2em;
                box-decoration-break: clone;
                -webkit-box-decoration-break: clone;
            }
            mark[${MARK}="contiguous"] {
                /* 小さくすると速く光る。GIF向けの初期値は2.4秒。 */
                --ac-gaming-speed: 2.4s;
                color: #351800 !important;
                background-color: #ffb347 !important;
                background-image: linear-gradient(115deg,
                    #ff8a18 0%, #ffd36a 12%, #ffae42 24%,
                    #ff79bd 34%, #bd92ff 42%, #91f3ed 49%,
                    #ffe89a 57%, #ff991f 70%, #ffca59 84%, #ff8a18 100%
                ) !important;
                background-size: 300% 100% !important;
                background-position: 0% 50%;
                border-bottom: 3px solid #e85c00;
                text-shadow: 0 0 2px #fff6d7, 0 0 7px #fff0b8;
                box-shadow: 0 0 5px #ff8a18aa, 0 0 13px #ffad3455;
                animation: ac-sequence-iridescence var(--ac-gaming-speed) ease-in-out infinite;
            }
            @keyframes ac-sequence-iridescence {
                0%, 100% {
                    background-position: 0% 50%;
                    box-shadow: 0 0 5px #ff8a18aa, 0 0 13px #ffad3455;
                    text-shadow: 0 0 2px #fff6d7, 0 0 7px #fff0b8;
                }
                50% {
                    background-position: 100% 50%;
                    box-shadow: 0 0 8px #ff891acc, 0 0 18px #ff73bd88, 0 0 25px #91f3ed66;
                    text-shadow: 0 0 3px #fff9e8, 0 0 10px #fff0b8;
                }
            }
            mark[${MARK}="subsequence"] {
                background: #cbeaff !important;
                border-bottom: 3px dashed #155d9c;
            }
            mark[${MARK}="check"] {
                background: #eee0ff !important;
                border-bottom: 3px dotted #7040a0;
            }
            .ac-sequence-notice {
                background: #f7fafc;
                color: #17212b;
                border: 1px solid #a8b7c7;
                border-left: 5px solid #a84600;
                border-radius: 5px;
                padding: 12px 16px;
                margin: 12px 0 20px;
                font-size: 14px;
                line-height: 1.9;
            }
            .ac-sequence-notice p { margin: 3px 0; }
            .ac-sequence-title {
                color: #a84600;
                text-shadow: 0 0 8px #ffb34777;
            }
        `;
        document.head.append(style);
    }

    function makeNotice() {
        const notice = document.createElement('aside');
        notice.className = 'ac-sequence-notice';
        notice.setAttribute('aria-label', '部分列・部分文字列の読み違い防止');
        const title = document.createElement('strong');
        title.className = 'ac-sequence-title';
        title.textContent = 'ゲーミング文字列：連続した区間？ 途中を飛ばしてもよい？';
        notice.append(title);
        for (const [kind, label, description] of [
            ['contiguous', '部分文字列 / substring / 部分配列 / subarray / 連続部分列', '通常：連続した区間。途中を飛ばさない。'],
            ['subsequence', '部分列 / subsequence', '通常：順序を保ち、途中を飛ばしてもよい。連続していてもよい。'],
            ['check', '非連続・not necessarily contiguous など', '否定や追加条件を確認。'],
        ]) {
            const p = document.createElement('p');
            const mark = document.createElement('mark');
            mark.setAttribute(MARK, kind);
            mark.textContent = label;
            p.append(mark, ` → ${description}`);
            notice.append(p);
        }
        const note = document.createElement('p');
        note.textContent = '色は用語の目印です。問題中の定義・条件を優先してください。';
        notice.append(note);
        return notice;
    }

    const roots = [...document.querySelectorAll(ROOT_SELECTOR)]
        .filter(root => !root.parentElement?.closest(ROOT_SELECTOR));
    if (!roots.length) return;
    installStyle();

    for (const root of roots) {
        if (root.dataset.acSequenceHighlightReady) continue;
        root.dataset.acSequenceHighlightReady = 'true';
        const notice = makeNotice();
        notice.hidden = true;
        root.before(notice);
        let timer;
        const observer = new MutationObserver(() => {
            clearTimeout(timer);
            timer = setTimeout(refresh, 100);
        });
        function refresh() {
            // 自分が付けた mark の変更を監視して無限に再走査しないようにする。
            observer.disconnect();
            try {
                notice.hidden = highlight(root).size === 0;
            } finally {
                observer.observe(root, { childList: true, subtree: true, characterData: true });
            }
        }
        refresh();
    }
})();

